'use strict';
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
const destinations=[{name:'Tân Cương',lat:21.527,lng:105.754,cost:160000,style:'Thiên nhiên',activity:'Dạo đồi chè, tìm hiểu cách pha và thưởng trà.'},{name:'Hồ Núi Cốc',lat:21.571,lng:105.681,cost:220000,style:'Nghỉ dưỡng',activity:'Tham quan không gian hồ, nghỉ ngơi và chụp ảnh.'},{name:'ATK Định Hóa',lat:21.799,lng:105.591,cost:120000,style:'Văn hóa',activity:'Tìm hiểu lịch sử và tham quan các điểm di tích.'},{name:'Thái Hải',lat:21.526,lng:105.8,cost:200000,style:'Gia đình',activity:'Khám phá văn hóa nhà sàn và trải nghiệm cộng đồng.'},{name:'La Bằng',lat:21.634,lng:105.585,cost:150000,style:'Thiên nhiên',activity:'Khám phá vùng chè, tận hưởng không gian xanh.'}];
const tours=globalThis.TRA_CATALOG.tours;
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function writeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Trình duyệt không cho phép lưu. Bạn có thể tải lịch trình về máy.');return false;}}
let favorites=readStore('tra-favorites',[]),activeTag='',currentPlan=null,map=null;
if(!Array.isArray(favorites))favorites=[];
function escapeHTML(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function showModal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
$('.close').onclick=()=>$('#modal').close();
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function filteredTours(){const location=$('#destination').value,days=+$('#duration').value,price=+$('#price').value;let result=tours.filter(t=>(!location||t.places.includes(location))&&(!days||t.days===days)&&(!price||t.price<=price)&&(!activeTag||t.tags.includes(activeTag)));if($('#sort').value==='asc')result.sort((a,b)=>a.price-b.price);if($('#sort').value==='desc')result.sort((a,b)=>b.price-a.price);return result;}
function renderTours(){const list=filteredTours();$('#result-count').textContent=list.length+' hành trình dành cho bạn';$('#tour-grid').innerHTML=list.map(tourCardHTML).join('')||'<div class="empty"><h3>Chưa có tour phù hợp</h3><p>Thử đổi bộ lọc hoặc thiết kế hành trình riêng của bạn.</p><button class="outline" id="clear-filters">Xóa bộ lọc</button></div>';}
$('#search').onsubmit=e=>{e.preventDefault();renderTours();$('#tours').scrollIntoView({behavior:'smooth'});};
$('#tags').onclick=e=>{const b=e.target.closest('[data-tag]');if(!b)return;activeTag=b.dataset.tag;$('#tags').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));renderTours();};
$('#sort').onchange=renderTours;
document.addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]'),tour=e.target.closest('[data-tour]'),tagBtn=e.target.closest('[data-filter-tag]');if(fav){let id=+fav.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];writeStore('tra-favorites',favorites);renderTours();}if(tagBtn){e.preventDefault();const clicked=tagBtn.dataset.filterTag;activeTag=activeTag===clicked?'':clicked;$('#tags').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x.dataset.tag===activeTag));renderTours();$('#tours').scrollIntoView({behavior:'smooth'});}if(tour){e.preventDefault();openTour(+tour.dataset.tour);}if(e.target.id==='clear-filters'){$('#search').reset();activeTag='';$('#tags').querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.tag===''));renderTours();}});
function openTour(id){const t=tours.find(t=>t.id===id);showModal(`<p class="eyebrow">TOUR MINH HỌA · ${t.days} NGÀY</p><h2>${t.name}</h2><p>${t.places.join(' → ')}</p><ol>${t.places.map(p=>`<li><b>${p}</b> — ${destinations.find(d=>d.name===p).activity}</li>`).join('')}</ol><h3>${money(t.price)} / người</h3><p class="micro">Giá biên tập, chưa phải báo giá nhà cung cấp.</p><button class="button" id="book-demo">Tạo phiếu đặt tour mẫu ↗</button><p class="micro">Phiếu chỉ lưu trên máy của bạn, không gửi đến đơn vị lữ hành.</p>`);$('#book-demo').onclick=()=>booking(t);}
function booking(t){showModal(`<p class="eyebrow">PHIẾU ĐẶT TOUR MẪU</p><h2>${t.name}</h2><p>Điền thông tin để lưu dự toán sơ bộ trên thiết bị.</p><p class="micro">${escapeHTML(t.pricingNote)} Nhân giá khởi điểm với số khách chỉ để tham khảo; không phải báo giá cho quy mô đoàn đã nhập.</p><form id="booking-form"><label>Họ và tên<input class="field" name="name" maxlength="80" required autocomplete="name"></label><div class="form-grid"><label>Ngày khởi hành<input name="date" type="date" required></label><label>Số khách<input name="guests" type="number" value="2" min="1" max="50" required></label></div><label>Email<input class="field" name="email" type="email" required autocomplete="email"></label><p id="booking-total">Dự toán: ${money(t.price*2)}</p><button class="button" type="submit">Lưu phiếu mẫu</button><p class="micro">Không thanh toán, không giữ chỗ. Thông tin chỉ lưu trên trình duyệt.</p></form>`);const form=$('#booking-form');form.elements.date.min=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());form.elements.guests.oninput=()=>$('#booking-total').textContent='Dự toán: '+money(t.price*(+form.elements.guests.value||0));form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));if(data.date<form.elements.date.min){toast('Vui lòng chọn ngày hiện tại hoặc tương lai.');return;}const total=t.price*+data.guests;const record={...data,tour:t.name,total};if(!writeStore('tra-booking',record))return;showModal(`<p class="eyebrow">ĐÃ LƯU TRÊN THIẾT BỊ</p><h2>Phiếu mẫu của bạn đã sẵn sàng.</h2><p>${escapeHTML(data.name)} · ${escapeHTML(data.date)} · ${data.guests} khách</p><h3>${money(total)}</h3><p>Đây là bản nháp, chưa phải xác nhận đặt chỗ. Không có yêu cầu nào được gửi đi.</p><button class="button" id="download-booking">Tải phiếu</button>`);$('#download-booking').onclick=()=>download('phieu-tour-mau.txt',JSON.stringify(record,null,2));};}
$('#places').innerHTML=destinations.map((d,i)=>`<label><input type="checkbox" value="${i}" ${i<2?'checked':''}> ${d.name}</label>`).join('');
function generatePlan({budget,people,days,style,selected}){let stops=selected.map(i=>destinations[i]);if(!stops.length)stops=[...destinations].sort((a,b)=>(b.style===style)-(a.style===style)||a.cost-b.cost).slice(0,Math.min(days*2,3));const visit=stops.reduce((s,d)=>s+d.cost,0),food=days*180000,stay=(days-1)*350000,transport=Math.ceil((days*600000/people)/10000)*10000,total=visit+food+stay+transport;return{budget,people,days,style,stops,visit,food,stay,transport,total,groupTotal:total*people};}
$('#planner').onsubmit=e=>{e.preventDefault();currentPlan=generatePlan({budget:+$('#budget').value,people:+$('#people').value,days:+$('#days').value,style:$('#style').value,selected:[...$('#places input:checked')].map(x=>+x.value)});renderPlan(currentPlan);};
function renderPlan(p){if(map){map.remove();map=null;}const result=$('#plan-result');result.hidden=false;result.innerHTML=`<p class="eyebrow">LỊCH TRÌNH ĐƯỢC GỢI Ý CHO BẠN</p><h3>${p.days} ngày ở miền xanh · ${p.people} người</h3><div class="plan-layout"><div><p class="budget-status ${p.total>p.budget?'over':''}">${p.total>p.budget?'Vượt ngân sách '+money(p.total-p.budget)+'/người. Hãy giảm điểm đến, số ngày hoặc tăng ngân sách.':'Trong ngân sách dự kiến của bạn.'}</p>${p.stops.length>p.days*2?'<p class="budget-status over">Nhiều điểm đến trong thời gian ngắn. Nên tăng số ngày để chuyến đi thoải mái hơn.</p>':''}<ol>${Array.from({length:p.days},(_,day)=>{let stops=p.stops.filter((_,i)=>Math.min(p.days-1,Math.floor(i*p.days/p.stops.length))===day);return `<li><b>Ngày ${day+1}</b><br>${stops.length?stops.map(s=>`${s.name}: ${s.activity}`).join('<br>'):'Tự do nghỉ ngơi, khám phá ẩm thực và trở về.'}</li>`;}).join('')}</ol><p>Trải nghiệm: ${money(p.visit)}<br>Ăn uống: ${money(p.food)}<br>Lưu trú: ${money(p.stay)}<br>Di chuyển nội vùng: ${money(p.transport)}</p><h3>${money(p.total)} <small>/ người</small></h3><p>Tổng nhóm: <b>${money(p.groupTotal)}</b></p></div><div><div id="map" class="map" aria-label="Bản đồ các điểm đến trong hành trình"></div><p class="micro">Tọa độ và đường nối minh họa giữa các khu vực; không phải tuyến đường ô tô. Mở chỉ đường để xem tuyến thực tế.</p><a id="directions" class="text-link" target="_blank" rel="noopener">Mở chỉ đường trên Google Maps ↗</a></div></div><div class="plan-actions"><button class="button" id="save-plan">Lưu hành trình</button><button class="outline" id="download-plan">Tải lịch trình</button></div><p class="micro">Gợi ý theo quy tắc và dự toán mẫu, chưa xác nhận dịch vụ hay giờ mở cửa. Phong cách: ${p.style}.</p>`;
const names=p.stops.map(s=>s.name+' Thái Nguyên Việt Nam');$('#directions').href='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent('Trung tâm Thái Nguyên Việt Nam')+'&destination='+encodeURIComponent(names.at(-1))+'&travelmode=driving'+(names.length>1?'&waypoints='+encodeURIComponent(names.slice(0,-1).join('|')):'');
if(window.L){map=L.map('map',{scrollWheelZoom:false});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:18}).addTo(map);const coords=p.stops.map(s=>[s.lat,s.lng]);p.stops.forEach((s,i)=>L.marker([s.lat,s.lng],{icon:L.divIcon({className:'pin',html:String(i+1),iconSize:[30,30]})}).addTo(map).bindPopup(s.name));L.polyline(coords,{color:'#225941',weight:4,dashArray:'8 8'}).addTo(map);map.fitBounds(L.latLngBounds(coords).pad(.25),{maxZoom:12});setTimeout(()=>map.invalidateSize(),100);}else{$('#map').classList.add('fallback-map');$('#map').innerHTML='<p>Bản đồ nền chưa tải được. Sơ đồ hành trình:</p><svg viewBox="0 0 400 300" role="img" aria-label="Sơ đồ các điểm đến"><path d="M50 30 L80 260" stroke="#225941" stroke-width="3" stroke-dasharray="5"/>'+p.stops.map((s,i)=>`<circle cx="${50+i*6}" cy="${30+i*230/Math.max(1,p.stops.length-1)}" r="12" fill="#225941"/><text x="100" y="${35+i*230/Math.max(1,p.stops.length-1)}" fill="#225941">${i+1}. ${s.name}</text>`).join('')+'</svg>';}
$('#save-plan').onclick=()=>{let plans=readStore('tra-plans',[]);if(!Array.isArray(plans))plans=[];if(writeStore('tra-plans',[p,...plans].slice(0,10)))toast('Đã lưu hành trình trên trình duyệt này.');};$('#download-plan').onclick=()=>download('hanh-trinh-thai-nguyen.txt',planText(p));result.scrollIntoView({behavior:'smooth',block:'start'});}
function planText(p){return `TRÀ JOURNEY — LỊCH TRÌNH MẪU\n${p.days} ngày, ${p.people} người, ${p.style}\n${p.stops.map((s,i)=>`${i+1}. ${s.name}: ${s.activity}`).join('\n')}\nƯớc tính/người: ${money(p.total)}\nTổng nhóm: ${money(p.groupTotal)}\nChưa xác nhận dịch vụ; không phải phiếu đặt chỗ.`;}
function download(name,text){const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#saved-plans').onclick=()=>{let list=readStore('tra-plans',[]);if(!Array.isArray(list))list=[];showModal('<h2>Hành trình đã lưu</h2>'+(list.length?list.map((p,i)=>`<p><b>${p.days} ngày · ${p.people} người · ${money(p.total)}/người</b><br>${p.stops.map(s=>escapeHTML(s.name)).join(' → ')}<br><button class="outline" data-load-plan="${i}">Xem hành trình</button></p>`).join(''):'<p>Bạn chưa lưu hành trình nào. Hãy tạo chuyến đi ở mục Khám phá.</p>')+'<p class="micro">Lưu riêng trên trình duyệt, tối đa 10 hành trình gần nhất.</p>');$('#modal-content').querySelectorAll('[data-load-plan]').forEach(b=>b.onclick=()=>{$('#modal').close();currentPlan=list[+b.dataset.loadPlan];renderPlan(currentPlan);});};
function renderReviews(){let saved=readStore('tra-reviews',[]);if(!Array.isArray(saved))saved=[];const local=saved.slice(0,3).map(r=>'<article class="tour-review-card"><h4>'+escapeHTML(r.title)+'</h4><p>'+escapeHTML(r.body)+'</p><div class="review-person"><b>'+escapeHTML(r.name)+'</b><small>Bài của bạn · Chỉ lưu trên thiết bị</small></div></article>').join('');$('#review-grid').innerHTML=local||'<p class="review-empty">Chưa có đánh giá từ khách hàng đã tham gia. Chúng tôi sẽ cập nhật sau khi tour được tổ chức.</p>'; }
$('#write-review').onclick=()=>{showModal('<h2>Kể về chuyến đi của bạn</h2><p>Bài viết lưu trên trình duyệt này, chưa đăng công khai.</p><form id="review-form"><label>Tên hiển thị<input class="field" name="name" maxlength="60" required></label><label>Tiêu đề<input class="field" name="title" maxlength="100" required></label><label>Đánh giá<select class="field" name="rating"><option value="5">5 — Rất hài lòng</option value="4">4 — Hài lòng</option value="3">3 — Bình thường</option value="2">2 — Chưa hài lòng</option value="1">1 — Không hài lòng</option></select></label><label>Trải nghiệm<textarea class="field" name="body" rows="4" maxlength="1200" required></textarea></label><button class="button" type="submit">Lưu bài viết trên thiết bị</button></form>');$('#review-form').onsubmit=e=>{e.preventDefault();const item=Object.fromEntries(new FormData(e.target));if(!item.name.trim()||!item.title.trim()||!item.body.trim()){toast('Vui lòng nhập đầy đủ nội dung.');return;}let items=readStore('tra-reviews',[]);if(!Array.isArray(items))items=[];if(writeStore('tra-reviews',[item,...items].slice(0,30))){renderReviews();$('#modal').close();toast('Đã lưu bài viết trên thiết bị của bạn.');}};};
renderTours();renderReviews();
